window.RP_SESSION={"id":"S-0d9259433628","messages":[{"id":"RP-III-0114786","time":"2026-06-16T14:08:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"애건 팔켄하인은 어설픈 용맹에 잠시 머무르는 동안 대부분의 시간을 방에서 지냈습니다.\n\n땅 안에서 지내던 세월은 그를 사회와 영 먼 곳으로 데려다두었습니다.\n\n누군가 말을 걸어와도 당황한 얼굴로 자리를 피했고, 늙고 주름진 얼굴이 창피해 넝마 같은 옷으로 얼굴을 가리거나 고개를 돌리기 일쑤였습니다.\n\n토르번은 그런 애건을 위해 새 의복을 가져다주었습니다.\n\n애건은 새 옷이 자신과 맞지 않는다며, 천이 까슬해 몸이 가렵다며 투정부렸지만\n\n형제에게 처음으로 받은 선물이 닳는 것이 아까워 장농의 상서랍에 고이 두었다는 것은 자신만이 알고있는 일이었습니다.","characters":["P-0039024aa219"]},{"id":"RP-III-0114787","time":"2026-06-16T14:16:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"시간이 조금 흐르면서, 애건은 어느 순간부터 자신의 몸이 조금씩 좋아지고 있음을 느꼈습니다. 그러나 그와 반대로, 자신의 형제인 토르번 팔켄하인은 어느순간 얼굴을 덮는 가면을 쓴 채 다른 이들을 피하고, 종종 홀로 사색에 잠기는 모습을 몰래 지켜봤습니다.\n\n그는 힘 주는 것 조차 떨리던 주먹을 쥐고 생각합니다.\n\n'나의 존재가, 형제의 생명을 갉아먹고 있구나.'\n\n그는 태어남과 동시에 토르번 팔켄하인에게 자신의 삶과 생명력이 바쳐졌음에도, 자신의 존재가 형제 곁에 머무는 것이 해가 되고 있다는 생각이 듭니다.\n\n'나는 저주받을 운명이었대도. 형제에겐 죄가 없지 않은가?'\n\n그러나 그것은 시기의 오해로 빚어진 일이었을 겁니다.\n\n오랜 세월 땅 속에서 홀로 지내며 약해졌던 몸이 이제야 정상적인 삶을 겪으며 아주 조금 좋아졌던 것이, 토르번 팔켄하인이 내적으로 겪던 갈등으로 비쳐진 외면으로금 애건은 오해하기 시작한 것이었습니다.","characters":["P-0039024aa219"]},{"id":"RP-III-0114788","time":"2026-06-16T14:18:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"지금은 맞지만 그때는 틀린 수 많은 오해와 사건들이 그러하듯이 말입니다.","characters":["P-0039024aa219"]},{"id":"RP-III-0114789","time":"2026-06-16T14:37:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그래서 애건은 이 곳에서 떠나고자 하는 생각이 들었습니다. \n\n어둡고 위험한 땅굴 속에서도 살아왔으니, 그보다 더 험한 세상이야 있겠냐는 생각도 잠시... 그의 각오를 무너뜨린 것은 사람들과의 관계를 이어가는 방법의 낯설음도, 자신은 고작 잠겨있는 문고리의 잠금장치를 푸는 방법도 모른다는 것도 아니었습니다.","characters":["P-0039024aa219"]},{"id":"RP-III-0114790","time":"2026-06-16T14:38:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"유리면에 비친 너무 주름지고 늙은 자신의 얼굴에. 그의 마음이 무너졌습니다.","characters":["P-0039024aa219"]},{"id":"RP-III-0114791","time":"2026-06-16T14:39:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그래서 그는 머무르기로 합니다.","characters":["P-0039024aa219"]},{"id":"RP-III-0114792","time":"2026-06-16T14:40:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"이곳이 안전해서가 아니라\n더 이상 몸 둘 곳이 없어서요.","characters":["P-0039024aa219"]},{"id":"RP-III-0114793","time":"2026-06-16T14:40:00+09:00","room":"RP III","name":"애건 팔켄하인","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-0039024aa219"]},{"id":"RP-III-0114794","time":"2026-06-16T14:40:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
